Literal.Value:
'{
  "signals": [
    {
      "name": "numberFormat",
      "value": ".0%"
    },
    {
      "name": "legendTitle",
      "value": "Compliance score"
    },
    {
      "name": "noDataLabel",
      "value": "No data"
    },
    {
      "name": "unmatchedLabel",
      "value": "Not on the map:"
    },
    {
      "name": "colorLow",
      "update": "pbiColor(''min'')"
    },
    {
      "name": "colorHigh",
      "update": "pbiColor(''max'')"
    },
    {
      "name": "colorNoData",
      "value": "#E1DFDD"
    },
    {
      "name": "highlightFiltered",
      "value": false
    },
    {
      "name": "colorHighlight",
      "update": "pbiColor(0)"
    },
    {
      "name": "scaleMin",
      "value": null
    },
    {
      "name": "scaleMax",
      "value": null
    },
    {
      "name": "borderColor",
      "value": "#FFFFFF"
    },
    {
      "name": "borderWidth",
      "value": 1
    },
    {
      "name": "showLabels",
      "value": true
    },
    {
      "name": "showValues",
      "value": true
    },
    {
      "name": "showLegend",
      "value": true
    },
    {
      "name": "labelFontSize",
      "value": 12
    },
    {
      "name": "legendFontSize",
      "value": 10
    },
    {
      "name": "fontFamily",
      "value": "Arial"
    },
    {
      "name": "textColor",
      "value": "#252423"
    },
    {
      "name": "textColorMuted",
      "value": "#605E5C"
    },
    {
      "name": "textColorOnDark",
      "value": "#FFFFFF"
    },
    {
      "name": "mapBox",
      "update": "geoBounds(''projection'', {type: ''FeatureCollection'', features: data(''geo'')})"
    },
    {
      "name": "mapWidth",
      "update": "mapBox[1][0] - mapBox[0][0]"
    },
    {
      "name": "sizeScale",
      "update": "clamp(mapWidth / 640, 0.7, 1.2)"
    },
    {
      "name": "labelSize",
      "update": "labelFontSize * sizeScale"
    },
    {
      "name": "statesPresent",
      "update": "length(data(''stateValues''))"
    },
    {
      "name": "valueExtent",
      "update": "extent(pluck(data(''stateValues''), ''value''))"
    },
    {
      "name": "isFiltered",
      "update": "highlightFiltered && statesPresent > 0 && statesPresent < 8"
    },
    {
      "name": "showScale",
      "update": "showLegend && !isFiltered && statesPresent > 0"
    },
    {
      "name": "colorDomain",
      "update": "[isValid(scaleMin) ? scaleMin : statesPresent > 0 ? valueExtent[0] : 0, isValid(scaleMax) ? scaleMax : statesPresent > 0 ? valueExtent[1] : 1]"
    },
    {
      "name": "legendX",
      "update": "mapBox[0][0]"
    },
    {
      "name": "legendY",
      "update": "mapBox[1][1] - (2 * legendFontSize + 18)"
    },
    {
      "name": "legendLength",
      "update": "clamp(mapWidth * 0.26, 90, 180)"
    },
    {
      "name": "legendBarY",
      "update": "legendY + legendFontSize + 5"
    },
    {
      "name": "unmatchedNames",
      "update": "pluck(data(''unmatched''), ''raw'')"
    }
  ],
  "width": {
    "signal": "pbiContainerWidth"
  },
  "height": {
    "signal": "pbiContainerHeight"
  },
  "padding": 4,
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "states",
      "values": [
        {
          "code": "NSW",
          "name": "New South Wales",
          "iso": "AU-NSW",
          "lon": 146.8,
          "lat": -32.5
        },
        {
          "code": "VIC",
          "name": "Victoria",
          "iso": "AU-VIC",
          "lon": 144.6,
          "lat": -36.9,
          "outLon": 141.6,
          "outLat": -39.6,
          "outAlign": "right"
        },
        {
          "code": "QLD",
