          "lat": -35.45,
          "outLon": 151.6,
          "outLat": -36.9,
          "outAlign": "left"
        }
      ]
    },
    {
      "name": "stateKeys",
      "source": "states",
      "transform": [
        {
          "type": "fold",
          "fields": [
            "code",
            "name",
            "iso"
          ],
          "as": [
            "form",
            "text"
          ]
        },
        {
          "type": "formula",
          "as": "key",
          "expr": "replace(upper(isValid(datum.text) ? datum.text + '''' : ''''), regexp(''[^A-Z]'', ''g''), '''')"
        }
      ]
    },
    {
      "name": "rows",
      "source": "dataset",
      "transform": [
        {
          "type": "formula",
          "as": "raw",
          "expr": "datum[''State'']"
        },
        {
          "type": "formula",
          "as": "key",
          "expr": "replace(upper(isValid(datum[''State'']) ? datum[''State''] + '''' : ''''), regexp(''[^A-Z]'', ''g''), '''')"
        },
        {
          "type": "formula",
          "as": "value",
          "expr": "toNumber(datum[''Value''])"
        },
        {
          "type": "lookup",
          "from": "stateKeys",
          "key": "key",
          "fields": [
            "key"
          ],
          "values": [
            "code"
          ]
        }
      ]
    },
    {
      "name": "stateValues",
      "source": "rows",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum.code) && isFinite(datum.value)"
        },
        {
          "type": "aggregate",
          "groupby": [
            "code"
          ],
          "fields": [
            "value",
            "__row__"
          ],
          "ops": [
            "sum",
            "min"
          ],
          "as": [
            "value",
            "__row__"
          ]
        }
      ]
    },
    {
      "name": "unmatched",
      "source": "rows",
      "transform": [
        {
          "type": "filter",
          "expr": "!isValid(datum.code) && isValid(datum.raw) && datum.raw !== ''''"
        },
        {
          "type": "aggregate",
          "groupby": [
            "raw"
          ]
        },
        {
          "type": "collect",
          "sort": {
            "field": "raw"
          }
        }
      ]
    },
    {
      "name": "tips",
      "source": "states",
      "transform": [
        {
          "type": "lookup",
          "from": "stateValues",
          "key": "code",
          "fields": [
            "code"
          ],
          "values": [
            "value"
          ]
        },
        {
          "type": "formula",
          "as": "State",
          "expr": "datum.name"
        },
        {
          "type": "formula",
          "as": "tipKey",
          "expr": "legendTitle ? legendTitle : ''Value''"
        },
        {
          "type": "formula",
          "as": "tipValue",
          "expr": "isValid(datum.value) ? format(datum.value, numberFormat) : noDataLabel"
        },
        {
          "type": "pivot",
          "groupby": [
            "State"
          ],
          "field": "tipKey",
          "value": "tipValue",
          "op": "max"
        }
      ]
    },
