      "format": {
        "type": "topojson",
        "feature": "states"
      }
    },
    {
      "name": "boundaries",
      "source": "geo",
      "transform": [
        {
          "type": "formula",
          "as": "code",
          "expr": "datum.properties.code"
        },
        {
          "type": "lookup",
          "from": "states",
          "key": "code",
          "fields": [
            "code"
          ],
          "values": [
            "name"
          ]
        },
        {
          "type": "lookup",
          "from": "stateValues",
          "key": "code",
          "fields": [
            "code"
          ],
          "values": [
            "value",
            "__row__"
          ]
        },
        {
          "type": "lookup",
          "from": "tips",
          "key": "State",
          "fields": [
            "name"
          ],
          "as": [
            "tip"
          ]
        },
        {
          "type": "formula",
          "as": "hasValue",
          "expr": "isValid(datum.value)"
        },
        {
          "type": "formula",
          "as": "area",
          "expr": "geoArea(''projection'', datum)"
        },
        {
          "type": "formula",
          "as": "box",
          "expr": "geoBounds(''projection'', datum)"
        },
        {
          "type": "formula",
          "as": "boxWidth",
          "expr": "datum.box[1][0] - datum.box[0][0]"
        }
      ]
    },
    {
      "name": "labels",
      "source": "states",
      "transform": [
        {
          "type": "filter",
          "expr": "showLabels"
        },
        {
          "type": "formula",
          "as": "canMove",
          "expr": "isValid(datum.outLon)"
        },
        {
          "type": "formula",
          "as": "outLon",
          "expr": "datum.canMove ? datum.outLon : datum.lon"
        },
        {
          "type": "formula",
          "as": "outLat",
          "expr": "datum.canMove ? datum.outLat : datum.lat"
        },
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": [
            "lon",
            "lat"
          ],
          "as": [
            "ax",
            "ay"
          ]
        },
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": [
            "outLon",
            "outLat"
          ],
          "as": [
            "ox",
            "oy"
          ]
        },
        {
          "type": "lookup",
          "from": "stateValues",
          "key": "code",
          "fields": [
            "code"
          ],
          "values": [
            "value",
            "__row__"
          ]
        },
        {
          "type": "lookup",
          "from": "tips",
          "key": "State",
          "fields": [
            "name"
          ],
          "as": [
            "tip"
          ]
        },
        {
          "type": "lookup",
          "from": "boundaries",
          "key": "code",
          "fields": [
            "code"
          ],
          "values": [
            "area",
            "boxWidth"
          ]
        },
        {
          "type": "formula",
          "as": "hasValue",
          "expr": "isValid(datum.value)"
        },
        {
          "type": "formula",
          "as": "twoLines",
          "expr": "showValues && datum.hasValue"
        },
        {
          "type": "formula",
          "as": "valueText",
          "expr": "datum.twoLines ? format(datum.value, numberFormat) : ''''"
        },
        {
          "type": "formula",
          "as": "textWidth",
          "expr": "max(length(datum.code), length(datum.valueText)) * labelSize * 0.62"
        },
        {
          "type": "formula",
          "as": "textHeight",
          "expr": "labelSize * (datum.twoLines ? 2.4 : 1.3)"
        },
        {
          "type": "formula",
          "as": "outside",
          "expr": "datum.canMove && (datum.area < datum.textWidth * datum.textHeight * 2.2 || datum.boxWidth < datum.textWidth * 1.4)"
        },
        {
          "type": "formula",
          "as": "x",
          "expr": "datum.outside ? datum.ox : datum.ax"
        },
        {
          "type": "formula",
          "as": "y",
          "expr": "datum.outside ? datum.oy : datum.ay"
        },
        {
          "type": "formula",
          "as": "align",
          "expr": "datum.outside ? datum.outAlign : ''center''"
        }
      ]
    }
  ],
  "projections": [
    {
      "name": "projection",
      "type": "conicEqualArea",
      "parallels": [
        -18,
        -36
      ],
      "rotate": [
        -132,
        0,
        0
      ],
      "fit": {
        "signal": "data(''geo'')"
      },
      "size": [
        {
          "signal": "width"
        },
        {
          "signal": "height"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "linear",
      "domain": {
        "signal": "colorDomain"
      },
      "range": {
        "signal": "[colorLow, colorHigh]"
      },
      "zero": false,
      "nice": false,
      "clamp": true
    }
  ],
  "legends": [
    {
      "fill": "color",
      "type": "gradient",
      "orient": "none",
      "direction": "horizontal",
      "legendX": {
        "signal": "legendX"
      },
      "legendY": {
        "signal": "legendY"
      },
      "title": {
        "signal": "legendTitle"
      },
      "format": {
        "signal": "numberFormat"
      },
      "values": {
        "signal": "colorDomain"
      },
      "gradientLength": {
        "signal": "legendLength"
      },
      "gradientThickness": 10,
      "gradientStrokeWidth": 0,
      "gradientOpacity": {
        "signal": "showScale ? 1 : 0"
      },
      "titleFont": {
        "signal": "fontFamily"
      },
      "titleFontSize": {
        "signal": "legendFontSize + 1"
      },
      "titleFontWeight": "normal",
      "titleColor": {
        "signal": "textColorMuted"
      },
      "titleLimit": {
        "signal": "legendLength + 90"
      },
      "titlePadding": 4,
      "titleOpacity": {
        "signal": "showScale ? 1 : 0"
      },
      "labelFont": {
        "signal": "fontFamily"
      },
      "labelFontSize": {
        "signal": "legendFontSize"
      },
      "labelColor": {
        "signal": "textColorMuted"
      },
      "labelOffset": 3,
      "labelOpacity": {
        "signal": "showScale ? 1 : 0"
      }
    }
  ],
  "marks": [
    {
      "type": "shape",
      "name": "stateShapes",
      "from": {
        "data": "boundaries"
      },
      "encode": {
        "update": {
          "fill": {
            "signal": "isFiltered ? (datum.hasValue ? colorHighlight : colorNoData) : (datum.hasValue ? scale(''color'', datum.value) : colorNoData)"
          },
          "stroke": {
            "signal": "borderColor"
          },
          "strokeWidth": {
            "signal": "borderWidth"
          },
          "strokeJoin": {
            "value": "round"
          },
          "tooltip": {
            "signal": "datum.tip"
          }
        }
      },
      "transform": [
        {
          "type": "geoshape",
          "projection": "projection"
        }
      ]
    },
    {
      "type": "rule",
      "name": "leaders",
      "from": {
        "data": "labels"
      },
      "encode": {
        "update": {
          "x": {
            "field": "ax"
          },
          "y": {
            "field": "ay"
          },
          "x2": {
            "signal": "datum.align === ''right'' ? datum.x + 3 : datum.x - 3"
          },
          "y2": {
            "field": "y"
          },
          "stroke": {
            "signal": "textColorMuted"
          },
          "strokeWidth": {
            "value": 1
          },
          "opacity": {
            "signal": "datum.outside ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "name": "labelCodes",
      "from": {
        "data": "labels"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x"
          },
          "align": {
            "field": "align"
          },
          "baseline": {
            "value": "middle"
          },
          "font": {
            "signal": "fontFamily"
          },
          "fontSize": {
            "signal": "labelSize"
          },
          "limit": {
            "signal": "labelSize * 8"
          },
          "fill": {
            "signal": "!datum.hasValue ? textColorMuted : datum.outside ? textColor : contrast(isFiltered ? (datum.hasValue ? colorHighlight : colorNoData) : (datum.hasValue ? scale(''color'', datum.value) : colorNoData), textColor) >= contrast(isFiltered ? (datum.hasValue ? colorHighlight : colorNoData) : (datum.hasValue ? scale(''color'', datum.value) : colorNoData), textColorOnDark) ? textColor : textColorOnDark"
          },
          "tooltip": {
            "signal": "datum.tip"
          },
          "y": {
            "signal": "datum.twoLines ? datum.y - labelSize * 0.6 : datum.y"
          },
          "text": {
            "field": "code"
          },
          "fontWeight": {
            "value": "bold"
          }
        }
      }
    },
    {
      "type": "text",
      "name": "labelValues",
      "from": {
        "data": "labels"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x"
          },
          "align": {
            "field": "align"
          },
          "baseline": {
            "value": "middle"
          },
          "font": {
            "signal": "fontFamily"
          },
          "fontSize": {
            "signal": "labelSize"
          },
          "limit": {
            "signal": "labelSize * 8"
          },
          "fill": {
            "signal": "!datum.hasValue ? textColorMuted : datum.outside ? textColor : contrast(isFiltered ? (datum.hasValue ? colorHighlight : colorNoData) : (datum.hasValue ? scale(''color'', datum.value) : colorNoData), textColor) >= contrast(isFiltered ? (datum.hasValue ? colorHighlight : colorNoData) : (datum.hasValue ? scale(''color'', datum.value) : colorNoData), textColorOnDark) ? textColor : textColorOnDark"
          },
          "tooltip": {
            "signal": "datum.tip"
          },
          "y": {
            "signal": "datum.y + labelSize * 0.6"
          },
          "text": {
            "field": "valueText"
          }
        }
      }
    },
    {
      "type": "rect",
      "name": "noDataSwatch",
      "encode": {
        "update": {
          "x": {
            "signal": "legendX + legendLength + 18"
          },
          "y": {
            "signal": "legendBarY"
          },
          "width": {
            "value": 10
          },
          "height": {
            "value": 10
          },
          "fill": {
            "signal": "colorNoData"
          },
          "opacity": {
            "signal": "showScale && statesPresent < 8 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "name": "noDataText",
      "encode": {
        "update": {
          "x": {
            "signal": "legendX + legendLength + 32"
          },
          "y": {
            "signal": "legendBarY + 5"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "noDataLabel"
          },
          "font": {
            "signal": "fontFamily"
          },
          "fontSize": {
            "signal": "legendFontSize"
          },
          "fill": {
            "signal": "textColorMuted"
          },
          "limit": {
            "value": 90
          },
          "opacity": {
            "signal": "showScale && statesPresent < 8 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "name": "unmatchedNote",
      "encode": {
        "update": {
          "x": {
            "signal": "legendX"
          },
          "y": {
            "signal": "legendY - 10"
          },
          "baseline": {
            "value": "bottom"
          },
          "text": {
            "signal": "length(unmatchedNames) ? unmatchedLabel + '' '' + join(unmatchedNames, '', '') : ''''"
          },
          "font": {
            "signal": "fontFamily"
          },
          "fontSize": {
            "signal": "legendFontSize"
          },
          "fill": {
            "signal": "textColorMuted"
          },
          "limit": {
            "signal": "mapWidth * 0.6"
          },
          "tooltip": {
            "signal": "length(unmatchedNames) ? {''Not on the map'': join(unmatchedNames, '', '')} : null"
          }
        }
      }
    }
  ]
